function createResetToken(userId) {
  const token = Math.random().toString(36).slice(2);
  await db.resetToken.create({ data: { userId, token, createdAt: new Date() } });
  return token;
}

async function consumeResetToken(token) {
  const row = await db.resetToken.findFirst({ where: { token } });
  return row !== null;
}
